package flatted

import (
	"encoding/json"
	"reflect"
	"strings"
	"testing"
)

type jsonTagged struct {
	Name   string `json:"name"`
	Age    int    `json:"age"`
	hidden string
}

type jsonCustom string

func (j jsonCustom) MarshalJSON() ([]byte, error) {
	return json.Marshal(string(j))
}

func TestStringifyAndParseComplexGraph(t *testing.T) {
	root := map[string]any{
		"name": "root",
	}
	list := []any{root}
	root["self"] = root
	root["list"] = list
	root["custom"] = jsonCustom("custom-value")

	s, err := Stringify(root, nil, 2)
	if err != nil {
		t.Fatalf("Stringify() error = %v", err)
	}
	if !strings.Contains(s, "\n  ") {
		t.Fatalf("expected indented output, got: %s", s)
	}

	parsed, err := Parse(s, nil)
	if err != nil {
		t.Fatalf("Parse() error = %v", err)
	}

	m, ok := parsed.(map[string]any)
	if !ok {
		t.Fatalf("expected map[string]any, got %T", parsed)
	}
	self, ok := m["self"].(map[string]any)
	if !ok {
		t.Fatalf("expected self map, got %T", m["self"])
	}
	if reflect.ValueOf(self).Pointer() != reflect.ValueOf(m).Pointer() {
		t.Fatalf("expected recursive self reference to be preserved")
	}

	arr, ok := m["list"].([]any)
	if !ok || len(arr) != 1 {
		t.Fatalf("expected list with one element, got %T len=%d", m["list"], len(arr))
	}
	firstMap, ok := arr[0].(map[string]any)
	if !ok {
		t.Fatalf("expected list[0] map, got %T", arr[0])
	}
	if reflect.ValueOf(firstMap).Pointer() != reflect.ValueOf(m).Pointer() {
		t.Fatalf("expected list[0] to reference root map")
	}
}

func TestStringifyWithWhitelistAndStructTags(t *testing.T) {
	obj := map[string]any{
		"keep": "yes",
		"drop": "no",
	}

	s, err := Stringify(obj, []string{"keep"}, nil)
	if err != nil {
		t.Fatalf("Stringify() error = %v", err)
	}
	parsed, err := Parse(s, nil)
	if err != nil {
		t.Fatalf("Parse() error = %v", err)
	}
	m := parsed.(map[string]any)
	if _, ok := m["keep"]; !ok {
		t.Fatalf("expected keep key in parsed output")
	}
	if _, ok := m["drop"]; ok {
		t.Fatalf("did not expect drop key in parsed output")
	}

	person := jsonTagged{Name: "Aegion", Age: 2, hidden: "secret"}
	s, err = Stringify(person, nil, nil)
	if err != nil {
		t.Fatalf("Stringify(struct) error = %v", err)
	}
	parsed, err = Parse(s, nil)
	if err != nil {
		t.Fatalf("Parse(struct) error = %v", err)
	}
	pm := parsed.(map[string]any)
	if _, ok := pm["name"]; !ok {
		t.Fatalf("expected json tag field name")
	}
	if _, ok := pm["hidden"]; ok {
		t.Fatalf("did not expect unexported field")
	}
}

func TestParseEdgeCases(t *testing.T) {
	if _, err := Parse("not-json", nil); err == nil {
		t.Fatalf("expected invalid JSON error")
	}

	v, err := Parse("[]", nil)
	if err != nil {
		t.Fatalf("Parse(empty) error = %v", err)
	}
	if v != nil {
		t.Fatalf("expected nil for empty input, got %T", v)
	}

	v, err = Parse(`[123]`, nil)
	if err != nil {
		t.Fatalf("Parse(scalar) error = %v", err)
	}
	if num, ok := v.(float64); !ok || num != 123 {
		t.Fatalf("expected scalar 123, got %v (%T)", v, v)
	}
}

func TestParseReviverForMapAndArray(t *testing.T) {
	seen := map[string]bool{}
	reviver := func(key string, value any) any {
		seen[key] = true
		if key == "a" {
			return float64(99)
		}
		return value
	}

	// Use numeric payloads to avoid string index ambiguity in this third-party parser.
	v, err := Parse(`[{"a":1,"b":[2,3]}]`, reviver)
	if err != nil {
		t.Fatalf("Parse(map reviver) error = %v", err)
	}
	m := v.(map[string]any)
	if m["a"] != float64(99) {
		t.Fatalf("expected key a to be revived")
	}
	if !seen["0"] || !seen["1"] || !seen["a"] || !seen["b"] || !seen[""] {
		t.Fatalf("expected reviver to run for array/map/root keys, got %v", seen)
	}

	v, err = Parse(`[[1,2]]`, func(key string, value any) any {
		if key == "1" {
			return float64(9)
		}
		return value
	})
	if err != nil {
		t.Fatalf("Parse(array reviver) error = %v", err)
	}
	arr := v.([]any)
	if arr[1] != float64(9) {
		t.Fatalf("expected revived array index 1")
	}
}

func TestToJSONAndFromJSON(t *testing.T) {
	root := map[string]any{"name": "root"}
	root["self"] = root

	j, err := ToJSON(root)
	if err != nil {
		t.Fatalf("ToJSON() error = %v", err)
	}
	from, err := FromJSON(j)
	if err != nil {
		t.Fatalf("FromJSON() error = %v", err)
	}

	m := from.(map[string]any)
	self := m["self"].(map[string]any)
	if reflect.ValueOf(self).Pointer() != reflect.ValueOf(m).Pointer() {
		t.Fatalf("expected recursive value from FromJSON")
	}

	if _, err := ToJSON(map[string]any{"fn": func() {}}); err == nil {
		t.Fatalf("expected ToJSON marshal error for function value")
	}
	if _, err := FromJSON(map[string]any{"fn": func() {}}); err == nil {
		t.Fatalf("expected FromJSON marshal error for function value")
	}
}
